def gen(rng):
    def fmt(n, left, right):
        return f'{n}\n{len(left)} ' + ' '.join(map(str, left)) + f'\n{len(right)} ' + ' '.join(map(str, right))
    def pick(n, cnt):
        s = set()
        while len(s) < cnt:
            s.add(rng.randint(0, n))
        return list(s)
    tests = [fmt(7, [7], [0]), fmt(5, [], [1, 4]), fmt(5, [2, 3], []), fmt(1, [0], []), fmt(1, [], [1]), fmt(10, [3, 7], [2, 5, 9])]
    tests.append(fmt(6, [0, 1, 2], [3, 4, 5]))
    tests.append(fmt(6, [3, 4, 5], [0, 1, 2]))
    for n in (2, 3, 5, 8, 10, 12, 15):
        for _ in range(3):
            cnt = rng.randint(1, min(n + 1, 8))
            pos = pick(n, cnt)
            rng.shuffle(pos)
            k = rng.randint(0, cnt)
            tests.append(fmt(n, pos[:k], pos[k:]))
    n = 10**9
    for ca, cb in ((50000, 50000), (100000, 0), (0, 100000), (1, 99999)):
        pos = pick(n, ca + cb)
        rng.shuffle(pos)
        tests.append(fmt(n, pos[:ca], pos[ca:]))
    return tests
